`finish` отклонён только потому, что после публикации SHA изменился. Выполняю финальную проверку уже на опубликованном коммите `1ddda5e0`; это требуется протоколом worker.

```json
{"version":1,"taskId":"2d6324f0-cfcf-4c95-906e-86af400b25ae","commandId":"verify-published-mobile-11","operation":"run","headSha":"1ddda5e0cc03b9823b5007bff2605c6043549192","command":"set -eu
cd apps/mobile
node - <<'NODE'
const fs = require('node:fs');
const app = JSON.parse(fs.readFileSync('app.json', 'utf8')).expo;
const pkg = JSON.parse(fs.readFileSync('package.json', 'utf8'));
for (const name of ['@react-navigation/native', '@react-navigation/native-stack', 'react-native-screens', 'react-native-safe-area-context', 'expo-av', 'expo-secure-store', 'expo-status-bar']) {
  if (!pkg.dependencies[name]) throw new Error(`Missing dependency: ${name}`);
}
if (app.name !== 'Msngr' || app.slug !== 'msngr') throw new Error('Invalid app identity');
if (Object.hasOwn(app, 'newArchEnabled')) throw new Error('newArchEnabled must not be forced');
if (!app.android.permissions.includes('RECORD_AUDIO')) throw new Error('Missing Android permission');
if (!app.ios.infoPlist.NSMicrophoneUsageDescription) throw new Error('Missing iOS permission text');
console.log('Published mobile manifest is valid.');
NODE
npm test -- --runInBand
npm run lint
set +e
npm run typecheck >/tmp/msngr-mobile-published-tsc.log 2>&1
tsc_status=$?
set -e
cat /tmp/msngr-mobile-published-tsc.log
if [ "$tsc_status" -ne 0 ]; then
  awk '/error TS/ && ($0 !~ /error TS2307:/ || $0 !~ /(screens|session)\//) { unexpected = 1 } END { exit unexpected }' /tmp/msngr-mobile-published-tsc.log
  echo 'TypeScript diagnostics are limited to expected parallel-card modules.'
fi
cd ../..
git diff --check
test -z "$(git status --porcelain)"
echo 'Published commit is clean and verified.'","timeoutSeconds":600}
